WITH quarterly_returns AS (SELECT d.d_year, d.d_quarter_seq, SUM(cr.cr_return_quantity) AS quarter_qty, SUM(cr.cr_return_amount) AS quarter_amount FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY d.d_year, d.d_quarter_seq), ranked_items AS (SELECT d.d_year, d.d_quarter_seq, cr.cr_item_sk, SUM(cr.cr_return_quantity) AS item_qty, SUM(cr.cr_return_amount) AS item_amount, RANK() OVER (PARTITION BY d.d_year ORDER BY SUM(cr.cr_return_quantity) DESC) AS year_rank FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY d.d_year, d.d_quarter_seq, cr.cr_item_sk) SELECT r.d_year, r.d_quarter_seq, r.cr_item_sk, r.item_qty, r.item_amount, q.quarter_qty, q.quarter_amount FROM ranked_items r JOIN quarterly_returns q ON r.d_year = q.d_year AND r.d_quarter_seq = q.d_quarter_seq WHERE r.year_rank <= 3 ORDER BY r.d_year, r.d_quarter_seq, r.year_rank
